"""Explain pollfree lifetime and locked/woken wait protocols."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1469': ('안내소를 철거하려면 먼저 이용자에게 폐쇄를 알리고, 아직 안내판을 보고 있는 사람이 안전하게 빠져나갈 시간도 줘야 합니다. 공지했다고 곧바로 안내판을 없애면 안 됩니다.', 'poll 대기열의 종료 통지와 RCU 지연 해제를 구별합니다.', '대기열 종료 통지 → 콜백의 등록 제거 → 필요한 RCU 수명 정리 → 실제 메모리 해제를 적으세요. 통지 함수에는 free가 없다고 표시하세요.', ['poll은 파일이나 장치의 준비 상태를 살피는 방식이고 epoll은 여러 대상을 관찰하는 데 쓰입니다. 드물게 poll용 대기열이 파일 객체보다 태스크의 수명에 묶여 먼저 사라질 수 있습니다. 그때 관찰자에게 대기열 종료를 알려야 합니다.', 'wake_up_pollfree는 목록에 항목이 있는지 보고 필요하면 내부 __wake_up_pollfree를 부릅니다. 내부 함수는 EPOLLHUP과 POLLFREE 사건 비트를 합쳐 key로 전달합니다. 이 key는 사라질 대기열에 대한 통지 정보이며 객체 주소를 따라 읽으라는 뜻이 아닙니다.', '관련 콜백은 이 통지에 맞춰 등록을 정리해야 합니다. 내부 함수는 처리 뒤 대기열이 아직 비어 있지 않으면 WARN_ON_ONCE로 경고합니다. 경고가 목록을 강제로 비우거나 잘못된 수명 관리를 자동으로 고치는 것은 아닙니다.', '함수 이름에 free가 있지만 이 함수가 head 메모리를 직접 해제하지는 않습니다. 통지와 등록 제거가 끝났어도 다른 CPU가 마지막 항목을 빼는 중 대기열에 접근하고 있을 수 있습니다. 빈 목록을 봤다는 사실과 모든 접근이 끝났다는 사실은 다릅니다.', '헤더는 호출자가 head의 해제를 RCU 규칙에 맞춰 지연해야 한다고 명시합니다. 예로 synchronize_rcu, call_rcu, 적절한 할당기 수명 규약을 듭니다. RCU는 관련된 이전 접근이 끝나기 전에 메모리가 너무 일찍 사라지지 않도록 하는 기술입니다.', '따라서 올바른 사용 종료 규약 아래에서 통지, 등록 정리, RCU 수명 보장, 실제 해제를 따로 추적하세요. 일반 파일을 닫을 때마다 무조건 이 함수를 부르는 규칙으로 외우는 것이 아니라 대기열과 파일의 수명이 다른 해당 상황에서 필요한 절차입니다.'], [('wake_up_pollfree는 head 메모리를 직접 free할까요?', ['네. 통지한 다음 즉시 메모리를 없애요', '아니요. 대기열이 사라질 것을 통지해요'], '함수는 콜백으로 종료 사건을 전달합니다. 헤더가 별도의 지연 해제를 호출자 책임으로 정하므로 이름의 free를 즉시 메모리 해제로 읽으면 안 됩니다.'), ('종료 통지 뒤 head를 없앨 때 지켜야 할 규칙은?', ['RCU에 맞게 해제를 지연하는 수명 규칙이에요', '사건 비트만 지우면 즉시 해제해도 돼요'], '마지막 등록 제거와 잠금 없는 관측이 겹칠 수 있습니다. 관련된 이전 접근이 끝나도록 수명을 보장해야 하므로 사건 비트 변경만으로 충분하지 않습니다.')]), 'os1470': ('명단을 잠그고 내 차례를 살피더라도, 기다리는 동안까지 명단을 잠가 두면 다른 사람이 일을 진행하기 어렵습니다. 잠깐 풀고 기다린 뒤 다시 잡아 확인합니다.', 'locked 대기의 호출 전후 잠금과 실제 잠드는 동안의 잠금을 구별합니다.', '정상: 잠금 보유 → 등록·상태 설정 → unlock → schedule → lock → 반환. 신호: 잠금 보유 → 등록·상태 설정 → 오류 반환을 나란히 그리세요.', ['do_wait_intr는 호출자가 대기열 잠금을 이미 잡은 상태에서 호출하는 내부 함수입니다. 잠금 아래 조건 검사와 대기자 등록을 이어 가는 사용법입니다. 이 전제가 없으면 함수 안의 unlock도 올바르게 사용할 수 없습니다.', '항목이 아직 연결되지 않았다면 목록 끝에 넣습니다. 그다음 TASK_INTERRUPTIBLE로 상태를 설정합니다. 이는 신호로 중단 가능한 기다림을 준비하는 것이며, 아직 schedule을 호출한 것은 아닙니다.', 'signal_pending으로 신호가 있는지 확인하고 있으면 -ERESTARTSYS를 반환합니다. 이 return은 spin_unlock보다 앞에 있으므로 잠금은 그대로 잡힌 상태입니다. 오류라고 언제나 잠금을 풀어 주는 함수는 아닙니다.', '신호가 없으면 spin_unlock, schedule, spin_lock 순서로 실행합니다. 실제로 기다리는 동안에는 대기열 잠금을 놓습니다. 다시 돌아오기 전에는 잠금을 재획득하므로 호출 전후는 잠금 보유, 중간 대기는 잠금 해제라는 차이가 있습니다.', 'do_wait_intr_irq는 풀 때 spin_unlock_irq, 다시 잡을 때 spin_lock_irq를 씁니다. 이 변형은 진입 시 인터럽트가 꺼진 잠금 문맥을 요구하며, 대기 동안 켜고 다시 잡을 때 끄는 규칙을 사용합니다. 단순 변형과 주변의 잠금 방식을 맞춰야 합니다.', '상위 locked 대기 매크로는 반복 종료 때 대기 항목을 제거하고 TASK_RUNNING을 복구합니다. 특히 초기 신호 경로는 잠금을 유지한 채 상태도 대기 준비 상태로 남을 수 있으므로 이 정리 계약까지 함께 읽어야 합니다. 내부 함수만 떼어 일반 대기로 쓰지 마세요.'], [('정상 경로에서 대기열 잠금을 잡은 채 schedule로 잠들까요?', ['네. 기다리는 내내 spinlock을 유지해요', '아니요. 풀고 기다린 뒤 다시 잡아요'], '본문의 순서는 unlock → schedule → lock입니다. 함수 진입과 반환 때 잡혀 있다는 사실을 잠든 구간에도 잡혀 있다는 뜻으로 해석하면 안 됩니다.'), ('처음 신호를 발견해 오류로 반환할 때 잠금을 풀까요?', ['아니요. 잠금을 유지한 채 반환해요', '네. 반드시 unlock한 다음 오류를 반환해요'], '신호의 return -ERESTARTSYS가 unlock보다 앞에 있습니다. 상위 코드는 이 잠금 보유 계약에 따라 항목과 상태를 정리합니다.')]), 'os1471': ('벨이 이미 울렸다는 표시가 있으면 또 잠들기 전에 확인해야 합니다. 일하는 사람에게 정지 요청이 왔을 때도 무조건 다시 잠들면 안 됩니다.', 'WOKEN 표시와 커널 스레드 정지 요청이 대기를 건너뛰게 하는 조건을 배웁니다.', 'WOKEN 없음·정지 없음 → 대기, WOKEN 있음 → 대기 생략, 정지 요청 있음 → 대기 생략을 쓰세요. 모두 뒤에서 상태 복구와 WOKEN 지우기를 거칩니다.', ['wait_woken은 먼저 mode로 받은 대기 상태를 설정합니다. WQ_FLAG_WOKEN은 깨우기 요청이 있었다는 표시 비트입니다. 비트는 0이나 1 한 칸이며 flags에는 여러 종류의 표시가 함께 들어 있습니다.', '조건은 WOKEN이 없고 kthread_should_stop_or_park도 거짓일 때입니다. kthread는 커널 안에서 일하는 스레드이고 stop은 종료 요청, park는 잠시 쉬도록 하는 요청입니다. 둘 중 하나라도 대기를 건너뛸 이유가 있으면 schedule_timeout을 부르지 않습니다.', '실제로 기다리면 schedule_timeout에 시간 한도를 주고 돌려받은 남은 시간을 timeout에 저장합니다. 대기를 건너뛰었다면 입력 시간 값이 그대로 남습니다. 반환값은 조건 성공 표시가 아니라 남은 시간입니다.', '어느 경로든 __set_current_state(TASK_RUNNING)으로 상태를 복구합니다. 이어 smp_store_mb로 WOKEN 비트를 지웁니다. 다른 표시 비트는 남겨 두며, 이 저장에는 깨우는 쪽과 관측 순서를 맞추는 배리어가 연결됩니다.', '함수 안에는 실제 공유 조건을 검사하는 코드나 대기 항목을 등록·제거하는 코드가 없습니다. 원문 예시는 woken_wake_function을 정한 항목을 먼저 등록하고, 조건 반복문 안에서 wait_woken을 사용한 다음 끝에서 제거합니다.', '따라서 WOKEN을 보았다고 필요한 데이터가 준비됐다고 단정하지 마세요. 깨어난 뒤 조건을 다시 검사하는 것은 호출자의 역할입니다. 정지·park 요청과 대기열 객체 수명도 호출자가 자신의 작업 흐름에 맞춰 관리해야 합니다.'], [('WOKEN 표시가 이미 있으면 반드시 schedule_timeout을 호출할까요?', ['네. 표시와 관계없이 항상 기다려요', '아니요. 그 대기 호출을 건너뛰어요'], '조건의 첫 부분이 WOKEN이 없을 때만 참입니다. 이미 표시가 있으면 기다리기보다 상태를 복구하고 표시를 정리하는 길로 갑니다.'), ('wait_woken이 항목 등록과 제거까지 모두 해 줄까요?', ['아니요. 호출자가 별도로 처리해야 해요', '네. 매번 add와 remove까지 실행해요'], '본문은 태스크 상태, WOKEN 비트, 시간 값을 다룹니다. 등록과 제거는 원문 사용 예제에서도 바깥에서 하므로 이 함수가 전부 한다는 답은 틀립니다.')]), 'os1472': ('잠들기 전에 벨 표시를 확인하는 사람과, 표시를 먼저 켜고 부르는 사람을 생각해 봅시다. 이미 깨어 있어 새로 깨울 필요가 없어도 벨 표시는 남길 수 있습니다.', 'WOKEN 설정 순서와 A·B·C 배리어의 역할을 구별합니다.', '깨우는 쪽: C 배리어 → WOKEN 켜기 → 기본 깨우기. 기다리는 쪽: A 상태 설정 → 필요하면 대기 → 실행 상태 복구 → B로 WOKEN 끄기를 그리세요.', ['woken_wake_function은 먼저 smp_mb를 실행합니다. 원문에서 C라고 표시한 메모리 배리어입니다. 배리어는 CPU 사이에서 자료 접근 순서를 맞추는 도구이며, 정해진 시간 동안 쉬는 타이머가 아닙니다.', '다음 문장은 flags |= WQ_FLAG_WOKEN입니다. 기존 다른 표시를 유지하면서 WOKEN을 켭니다. 그 뒤에야 default_wake_function을 호출하고 그 결과를 반환합니다. 깨우기 성공 뒤에만 표시를 켜는 순서가 아닙니다.', '따라서 기본 깨우기가 0을 반환해도 이 함수가 수행한 WOKEN 설정을 취소하는 코드는 없습니다. 예를 들어 태스크가 이미 실행 가능한 상태라 새로 깨우지 않았어도 표시를 먼저 남기는 흐름입니다. 동시에 기다리는 쪽이 나중에 비트를 지울 수 있으므로 표시가 영원히 남는다는 뜻은 아닙니다.', 'wait_woken의 A는 대기 상태 설정 쪽 배리어로, 기본 깨우기 과정의 전체 배리어와 연결됩니다. 기다리는 쪽이 WOKEN을 보거나 깨우는 쪽이 대기 상태를 보도록 순서를 맞춰, 둘 다 상대의 표시를 놓치는 상황을 피하려는 규약입니다.', 'wait_woken이 WOKEN을 지우는 B는 이 콜백의 C와 연결됩니다. 앞선 조건 변경을 기다리는 쪽이 보거나 새 WOKEN 설정이 지우기보다 뒤의 갱신으로 남도록 순서를 맞춥니다. 여러 CPU의 관측 문제라 문장 순서를 마음대로 옮겨도 같은 동작이라고 할 수 없습니다.', '이 콜백에는 목록 제거가 없습니다. autoremove_wake_function과 달리 호출자가 항목을 따로 제거해야 합니다. 종이에 실행 순서를 그려 보는 것은 원리 이해에 도움이 되지만 실제 CPU의 모든 메모리 순서가 검증됐다는 뜻은 아닙니다.'], [('기본 깨우기가 0이면 이 함수가 WOKEN 설정을 취소할까요?', ['네. 성공했을 때만 표시를 켜요', '아니요. 기본 깨우기 호출 전에 이미 켭니다'], '본문은 C 배리어 → WOKEN 설정 → 기본 깨우기 순서이며 결과에 따라 설정을 되돌리는 분기가 없습니다. 다른 쪽의 이후 비트 정리는 별도 동작입니다.'), ('woken_wake_function은 항목을 자동으로 목록에서 제거할까요?', ['아니요. 별도 제거가 필요해요', '네. autoremove와 같은 삭제를 해요'], '이 함수는 배리어, 비트 설정, 기본 깨우기만 수행합니다. 목록 삭제 호출이 없으므로 이름이 비슷한 autoremove의 정리 계약을 그대로 적용하면 안 됩니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_363.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
